    def is_letter(c):
        return c.isalpha()

    # Function to reverse case of a letter
    def reverse_case(c):
        if c.islower():
            return c.upper()
        else:
            return c.lower()

    # Check if the string contains any letters
    if not any(is_letter(c) for c in s):
        return s[::-1]

